<form class="card-s mb-3 row g-2 align-items-end" method="get">
  <div class="col-12 col-md-3"><label class="form-label" for="term">الفصل</label><select class="form-select" id="term" name="term"><?php foreach ($terms as $t): ?><option value="<?= (int)$t['id'] ?>" <?= $termId === (int)$t['id'] ? 'selected' : '' ?>><?= e($t['name']) ?><?= $t['grades_locked'] ? ' 🔒' : '' ?></option><?php endforeach; ?></select></div>
  <div class="col-12 col-md-5"><label class="form-label" for="section">الشعبة</label><select class="form-select" id="section" name="section"><option value="">— اختر —</option><?php foreach ($sections as $s): ?><option value="<?= (int)$s['id'] ?>" <?= $secId === (int)$s['id'] ? 'selected' : '' ?>><?= e($s['grade_name'] . ' / ' . $s['name']) ?></option><?php endforeach; ?></select></div>
  <div class="col-12 col-md-4 d-flex gap-2"><button class="btn btn-primary flex-fill" type="submit">عرض</button><button class="btn btn-outline-dark" type="submit" name="final" value="1" title="تجميع كل الفصول">النتيجة النهائية</button><?php if ($res && can('reports.export')): ?><a class="btn btn-outline-success" href="<?= url('school/results.xlsx?term=' . $termId . '&section=' . $secId) ?>"><i class="bi bi-file-earmark-excel"></i> Excel</a><?php endif; ?></div>
</form>
<?php if ($res): $locked = (bool)$res['term']['grades_locked']; ?>
<div class="d-flex flex-wrap gap-2 align-items-center mb-3"><h2 class="h5 mb-0"><?= e($res['section']['grade_name'] . ' / ' . $res['section']['name']) ?> — <?= e($res['term']['name']) ?></h2><input type="hidden" id="isFinal" value="<?= $final ? 1 : 0 ?>">
  <span class="badge text-bg-secondary">النجاح من <?= (float)$res['scheme']['pass_score'] ?> / <?= (float)$res['scheme']['max_score'] ?></span><?= $locked ? '<span class="badge text-bg-dark">الدرجات مقفلة</span>' : '' ?>
  <span class="ms-auto d-flex flex-wrap gap-2">
    <?php if ($final): ?><?php if (can('reportcards.issue')): ?><button class="btn btn-primary" data-api="<?= url('api/v1/school/report-cards/issue-final') ?>" data-body='<?= e(json_encode(['year_id' => $yearId, 'section_id' => $secId])) ?>' data-confirm="إصدار الشهادة النهائية؟ تتطلب قفل كل الفصول."><i class="bi bi-award"></i> إصدار الشهادة النهائية</button>
      <button class="btn btn-outline-primary" data-api="<?= url('api/v1/school/report-cards/issue-final') ?>" data-body='<?= e(json_encode(['year_id' => $yearId, 'section_id' => $secId, 'allow_incomplete' => 1])) ?>' data-confirm="إصدار جزئي (مسوّدة)؟">إصدار جزئي</button><?php endif; ?>
    <?php elseif (can('grades.approve')): ?><?php if (!$locked): ?><button class="btn btn-outline-dark" data-api="<?= url('api/v1/school/terms/' . $termId . '/lock') ?>" data-confirm="قفل درجات الفصل لكل الشعب؟">قفل الفصل</button><?php else: ?><button class="btn btn-outline-warning" data-api="<?= url('api/v1/school/terms/' . $termId . '/unlock') ?>" data-prompt="سبب فتح القفل (يُسجَّل):">فتح القفل</button><?php endif; ?><?php endif; ?>
    <?php if (!$final && can('reportcards.issue')): ?><button class="btn btn-primary" data-api="<?= url('api/v1/school/report-cards/issue') ?>" data-body='<?= e(json_encode(['term_id' => $termId, 'section_id' => $secId])) ?>' data-confirm="إصدار شهادات الفصل لهذه الشعبة؟"><i class="bi bi-award"></i> إصدار الشهادات</button>
      <button class="btn btn-outline-primary" data-api="<?= url('api/v1/school/report-cards/issue') ?>" data-body='<?= e(json_encode(['term_id' => $termId, 'section_id' => $secId, 'allow_incomplete' => 1])) ?>' data-confirm="إصدار شهادات جزئية تتضمن نتائج غير مكتملة/غير معتمدة؟ ستُعلَّم كمسوّدة.">إصدار جزئي</button><?php endif; ?>
    <?php if ($cards): ?><a class="btn btn-outline-secondary" target="_blank" href="<?= url('school/report-cards/print?term=' . $termId . '&section=' . $secId) ?>"><i class="bi bi-printer"></i> طباعة الكل</a><?php endif; ?></span></div>
<?php if ($res['unassessed']): ?><div class="alert alert-warning">مواد بلا أي تقييم في هذا الفصل (مستثناة من المعدل): <?= e(implode('، ', $res['unassessed'])) ?></div><?php endif; ?>
<div class="card-s"><?php if (!$res['students']): ?><div class="empty-state">لا يوجد طلاب في الشعبة.</div><?php else: ?>
<div class="table-responsive"><table class="table table-sm align-middle table-cards"><thead><tr><th>الترتيب</th><th>الطالب</th><?php foreach ($res['subjects'] as $s): ?><th><?= e($s['name']) ?></th><?php endforeach; ?><th>المعدل %</th><th>التقدير</th><th>النتيجة</th></tr></thead><tbody>
<?php foreach ($res['students'] as $st): ?><tr><td data-label="الترتيب"><?= $st['rank'] ?? '—' ?></td><td data-label="الطالب"><?= e($st['full_name']) ?><?= !$st['complete'] || !$st['all_approved'] ? ' <span class="badge text-bg-warning" title="نتائج غير مكتملة أو غير معتمدة">!</span>' : '' ?></td>
  <?php foreach ($res['subjects'] as $s): $x = $st['subjects'][$s['id']]; ?><td data-label="<?= e($s['name']) ?>" class="<?= $x['passed'] === false ? 'text-danger fw-bold' : '' ?>"><?= $x['has_assessments'] ? (float)$x['total'] : '—' ?></td><?php endforeach; ?>
  <td data-label="المعدل %"><?= $st['average'] ?? '—' ?></td><td data-label="التقدير"><?= e($st['letter'] ?? '—') ?></td><td data-label="النتيجة"><?= e($st['result'] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<?php if ($cards): ?><div class="card-s mt-3"><h3 class="h6">الشهادات المُصدرة (<?= count($cards) ?>)</h3><div class="d-flex flex-wrap gap-2"><?php foreach ($cards as $c): ?><a class="btn btn-sm btn-outline-primary" target="_blank" href="<?= url('school/report-cards/' . (int)$c['id'] . '/print') ?>"><?= e($c['full_name']) ?></a><?php endforeach; ?></div></div><?php endif; ?>
<?php elseif ($termId): ?><div class="card-s empty-state"><i class="bi bi-award"></i>اختر الفصل والشعبة لعرض النتائج.</div><?php endif; ?>
<?php if ($cmp): ?><div class="card-s mt-3"><h3 class="h6">مقارنة الشعب (متوسط الفصل)</h3><div class="table-responsive"><table class="table table-sm table-cards"><thead><tr><th>الشعبة</th><th>الطلاب</th><th>المتوسط %</th><th>الأعلى</th><th>الأدنى</th><th>الناجحون</th></tr></thead><tbody>
<?php foreach ($cmp as $c): ?><tr><td data-label="الشعبة"><?= e($c['grade'] . ' / ' . $c['section']) ?></td><td data-label="الطلاب"><?= $c['students'] ?></td><td data-label="المتوسط"><?= $c['average'] ?? '—' ?></td><td data-label="الأعلى"><?= $c['highest'] ?? '—' ?></td><td data-label="الأدنى"><?= $c['lowest'] ?? '—' ?></td><td data-label="الناجحون"><?= $c['passed'] ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
